def _naive(y: np.ndarray) -> np.ndarray:
    return np.repeat(y[-1], H)

def _naive_estacional(y: np.ndarray) -> np.ndarray:
    return y[-H:].copy()

def _media_movil_estacional(y: np.ndarray, semanas: int = 4) -> np.ndarray:
    w = y[-H * semanas:].reshape(semanas, H)
    return w.mean(axis=0)

lgbm.codigo:
def _rasgos_lags(y: np.ndarray, o: int) -> tuple[dict, float]:
    nivel = y[o - H + 1: o + 1].mean()
    v = y[o - LAGS + 1: o + 1][::-1] / nivel  # v[0] = y[o]
    r = {f"lag{k}": v[k] for k in range(LAGS)}
    r["mm_sem_ant"] = y[o - 2 * H + 1: o - H + 1].mean() / nivel  # semana anterior (tendencia corta)
    r["mm_3sem"] = y[o - 3 * H + 1: o + 1].mean() / nivel
    return r, nivel

def directo(exog: list[str]):
    def f(hist: pd.DataFrame, fut: pd.DataFrame) -> pd.DataFrame:
        X, obj, _, Xf, nivel = rasgos(hist, fut, exog)
        m = lgb.LGBMRegressor(**PARAMS).fit(X, obj)
        return salida(fut.index, m.predict(Xf) * nivel)

    return f

walk_forward.codigo:
def partir(grilla: pd.DataFrame, origen) -> tuple[pd.DataFrame, pd.DataFrame]:
    origen = pd.Timestamp(origen)
    hist = grilla.loc[grilla.index <= origen].copy()
    fut = grilla.loc[grilla.index > origen].iloc[:H].drop(columns=["y", "y_modelo"]).copy()
    return hist, fut

def escala_mase(hist: pd.DataFrame) -> float:
    y = hist["y"].to_numpy(dtype=float)
    e = np.abs(y[H:] - y[:-H])
    return float(np.nanmean(e))

plan.codigo:
def factores(previas: pd.DataFrame, metodo: str, ps, por: list[str] = ["segmento"]) -> pd.DataFrame:
    d = previas[(previas[metodo] > 0) & previas["y"].notna()]
    d = d.assign(r=d["y"] / d[metodo])
    filas = []
    for k, x in d.groupby(por):
        k = k if isinstance(k, tuple) else (k,)
        filas.append({**dict(zip(por, k)), "n_errores": len(x),
                      **{p: float(np.percentile(x["r"], p)) for p in ps}})
    return pd.DataFrame(filas)

def elegir_p(curva: pd.DataFrame, metodo: str = "lgbm") -> int:
    c = curva[curva["metodo"] == metodo].sort_values(["costo_por_vianda", "p"])
    return int(c["p"].iloc[0])

